L94: export function applyPlan(baseDir, plan) {
L95:   mkdirSync(join(baseDir, "pending"), { recursive: true });
L96:   mkdirSync(join(baseDir, "awarded"), { recursive: true });
L97:   for (const m of plan.moves) {
L98:     const from = join(locDir(baseDir, m.from), m.name);
L99:     const to = join(baseDir, m.to, m.name);
L100:     try { if (existsSync(from)) renameSync(from, to); } catch (e) { /* keep going */ }
L101:   }
L102:   for (const c of plan.creates) {
L103:     try { mkdirSync(join(baseDir, c.kind, c.name), { recursive: true }); } catch (e) { /* keep going */ }
L104:   }
L105:   for (const d of plan.deletes) {
L106:     try { rmSync(join(locDir(baseDir, d.loc), d.name), { recursive: true, force: true }); } catch (e) { /* keep going */ }
L107:   }
L108: }
