L110: async function apiGet(apiBase, path, token) {
L111:   const res = await fetch(apiBase + path, { headers: { "freelancer-oauth-v1": token } });
L112:   if (!res.ok) throw new Error("HTTP " + res.status);
L113:   const json = await res.json();
L114:   if (!json || json.status !== "success") throw new Error((json && (json.message || json.error_code)) || "API error");
L115:   return json.result;
L116: }
