L118: export async function fetchBids(apiBase, token) {
L119:   const self = await apiGet(apiBase, "/users/0.1/self", token);
L120:   const selfId = self && self.id;
L121:   const bids = [];
L122:   let offset = 0;
L123:   for (;;) {
L124:     const path = "/projects/0.1/bids?bidders%5B%5D=" + selfId +
L125:       "&project_details=true&limit=50&offset=" + offset;
L126:     const result = await apiGet(apiBase, path, token);
L127:     const list = (result && result.bids) || [];
L128:     const projects = (result && result.projects) || {};
L129:     for (const b of list) {
L130:       const p = projects[b.project_id] || {};
L131:       bids.push({
L132:         id: b.project_id,
L133:         title: p.title || "",
L134:         status: b.frontend_bid_status || (b.retracted ? "revoked" : "active"),
